function validate([nums, k]) {
  if (!Array.isArray(nums) || nums.length < 2 || nums.length > 200000) return 'nums needs 2 to 200000 values.';
  if (nums.some(v => !Number.isInteger(v) || v < 1 || v > 1e9)) return 'Each value of nums is an integer from 1 to 10^9.';
  if (!Number.isInteger(k) || k < 1 || k > 1e9) return 'k is an integer from 1 to 10^9.';
  // Merged values come out in non-decreasing order, so two queues replay the process after one sort.
  const sorted = nums.slice().sort((a, b) => a - b);
  if (sorted[sorted.length - 1] >= k) return null;
  const made = [];
  let i = 0, j = 0;
  const take = () => (j >= made.length || (i < sorted.length && sorted[i] <= made[j])) ? sorted[i++] : made[j++];
  while (sorted.length - i + made.length - j >= 2) {
    const value = 2 * take() + take();
    if (value >= k) return null;
    made.push(value);
  }
  return 'No number of operations makes every element at least k.';
}

