function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  // Merging everything gives the largest value the process can reach; the answer exists when it reaches k.
  const reachable = (nums, k) => {
    const sorted = nums.slice().sort((a, b) => a - b);
    const made = [];
    let i = 0, j = 0;
    const take = () => (j >= made.length || (i < sorted.length && sorted[i] <= made[j])) ? sorted[i++] : made[j++];
    while (sorted.length - i + made.length - j >= 2) {
      const x = take(), y = take();
      if (2 * x + y >= k) return true;
      made.push(2 * x + y);
    }
    return Math.max(...nums) >= k;
  };
  for (;;) {
    let nums, k;
    if (size === 'large') {
      const mode = int(0, 2);
      const top = mode === 0 ? 1e9 : mode === 1 ? 1e6 : 1000;
      nums = Array.from({ length: 2000 }, () => int(1, top));
      k = mode === 0 ? int(5e8, 1e9) : mode === 1 ? 1e9 : int(1e6, 1e9);
    } else {
      const n = int(2, 8);
      const top = [3, 10, 50][int(0, 2)];
      nums = Array.from({ length: n }, () => int(1, top));
      k = int(1, top * 4);
    }
    if (reachable(nums, k)) return [nums, k];
  }
}
